import heapq

def minRoomsWithBuffer(intervals, buffer):
    ready = []  # times at which each room is clean again
    for a, b in sorted(intervals):
        if ready and ready[0] <= a:
            heapq.heapreplace(ready, b + buffer)
        else:
            heapq.heappush(ready, b + buffer)
    return len(ready)

