function minRoomsWithBuffer(intervals, buffer) {
    const iv = intervals.slice().sort((p, q) => p[0] - q[0]);
    const heap = []; // min-heap of times each room is clean again
    const push = v => {
        heap.push(v);
        for (let i = heap.length - 1; i > 0;) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
        }
    };
    const replaceTop = v => {
        heap[0] = v;
        for (let i = 0; ;) {
            const l = 2 * i + 1, r = l + 1;
            let m = i;
            if (l < heap.length && heap[l] < heap[m]) m = l;
            if (r < heap.length && heap[r] < heap[m]) m = r;
            if (m === i) break;
            [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
        }
    };
    for (const [a, b] of iv) {
        if (heap.length && heap[0] <= a) replaceTop(b + buffer);
        else push(b + buffer);
    }
    return heap.length;
}

