type readyHeap []int

func (h readyHeap) Len() int            { return len(h) }
func (h readyHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h readyHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *readyHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *readyHeap) Pop() interface{} {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

func minRoomsWithBuffer(intervals [][]int, buffer int) int {
    iv := append([][]int{}, intervals...)
    sort.Slice(iv, func(i, j int) bool { return iv[i][0] < iv[j][0] })
    ready := &readyHeap{} // times each room is clean again
    for _, p := range iv {
        if ready.Len() > 0 && (*ready)[0] <= p[0] {
            heap.Pop(ready)
        }
        heap.Push(ready, p[1]+buffer)
    }
    return ready.Len()
