class MinHeap {
    constructor(less) { this.a = []; this.less = less; }
    get size() { return this.a.length; }
    peek() { return this.a[0]; }
    push(v) {
        const a = this.a; a.push(v);
        for (let i = a.length - 1; i > 0;) {
            const p = (i - 1) >> 1;
            if (!this.less(a[i], a[p])) break;
            [a[p], a[i]] = [a[i], a[p]]; i = p;
        }
    }
    pop() {
        const a = this.a, top = a[0], last = a.pop();
        if (a.length) {
            a[0] = last;
            for (let i = 0; ;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < a.length && this.less(a[l], a[m])) m = l;
                if (r < a.length && this.less(a[r], a[m])) m = r;
                if (m === i) break;
                [a[m], a[i]] = [a[i], a[m]]; i = m;
            }
        }
        return top;
    }
}

function mostBooked(n, meetings) {
    const ms = meetings.slice().sort((a, b) => a[0] - b[0]);
    const free = new MinHeap((x, y) => x < y);
    const busy = new MinHeap((x, y) => x[0] < y[0] || (x[0] === y[0] && x[1] < y[1])); // [end, room]
    for (let r = 0; r < n; r++) free.push(r);
    const count = new Array(n).fill(0);
    for (const [s, e] of ms) {
        while (busy.size && busy.peek()[0] <= s) free.push(busy.pop()[1]);
        let r;
        if (free.size) {
            r = free.pop();
            busy.push([e, r]);
        } else {
            const [t, room] = busy.pop(); // wait for the earliest room
            r = room;
            busy.push([t + e - s, r]);
        }
        count[r]++;
    }
    let best = 0;
    for (let r = 1; r < n; r++) if (count[r] > count[best]) best = r;
    return best;
}

