                r = free.poll();
                busy.add(new long[]{m[1], r});
            } else {
                long[] top = busy.poll(); // wait for the earliest room
                r = (int) top[1];
                busy.add(new long[]{top[0] + m[1] - m[0], r});
            }
            count[r]++;
        }
        int best = 0;
        for (int r = 1; r < n; r++) if (count[r] > count[best]) best = r;
