import (
    "container/heap"
    "sort"
)

// pairHeap is a min-heap of [2]int compared lexicographically.
type pairHeap [][2]int

func (h pairHeap) Len() int { return len(h) }
func (h pairHeap) Less(i, j int) bool {
    if h[i][0] != h[j][0] {
        return h[i][0] < h[j][0]
    }
    return h[i][1] < h[j][1]
}
func (h pairHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *pairHeap) Push(x interface{}) { *h = append(*h, x.([2]int)) }
func (h *pairHeap) Pop() interface{} {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

func mostBooked(n int, meetings [][]int) int {
    ms := append([][]int{}, meetings...)
    sort.Slice(ms, func(i, j int) bool { return ms[i][0] < ms[j][0] })
    free := &pairHeap{} // [room, 0]
    busy := &pairHeap{} // [end, room]
    for r := 0; r < n; r++ {
        heap.Push(free, [2]int{r, 0})
    }
    count := make([]int, n)
    for _, m := range ms {
        s, e := m[0], m[1]
        for busy.Len() > 0 && (*busy)[0][0] <= s {
            top := heap.Pop(busy).([2]int)
            heap.Push(free, [2]int{top[1], 0})
        }
        var r int
        if free.Len() > 0 {
            r = heap.Pop(free).([2]int)[0]
            heap.Push(busy, [2]int{e, r})
        } else {
            top := heap.Pop(busy).([2]int) // wait for the earliest room
            r = top[1]
            heap.Push(busy, [2]int{top[0] + e - s, r})
        }
        count[r]++
    }
    best := 0
    for r := 1; r < n; r++ {
        if count[r] > count[best] {
            best = r
        }
    }
    return best
}

