class Solution {
    public int minMeetingRooms(int[][] intervals) {
        // By start, then end, so a zero-length meeting frees its room before a longer one at the same time
        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        List<Integer> activeEnds = new ArrayList<>(); // end times of rooms in use
        int maxRooms = 0;
        for (int[] meeting : intervals) {
            // Free every room whose meeting has ended by now
            activeEnds.removeIf(end -> end <= meeting[0]);
            activeEnds.add(meeting[1]);
            maxRooms = Math.max(maxRooms, activeEnds.size());
        }
        return maxRooms;
    }
