class Solution {
    public int minMeetingRooms(int[][] intervals) {
        // Events as {time, kind}: at equal times, ends (0) free rooms first,
        // then zero-length meetings (1) use a room for an instant, then starts (2)
        List<int[]> events = new ArrayList<>();
        for (int[] iv : intervals) {
            if (iv[0] == iv[1]) {
                events.add(new int[]{iv[0], 1});
            } else {
                events.add(new int[]{iv[0], 2});
                events.add(new int[]{iv[1], 0});
            }
        }
        events.sort((x, y) -> x[0] != y[0] ? Integer.compare(x[0], y[0]) : Integer.compare(x[1], y[1]));
        int rooms = 0, maxRooms = 0;
        for (int[] ev : events) {
            if (ev[1] == 0) rooms--;
            else if (ev[1] == 1) maxRooms = Math.max(maxRooms, rooms + 1);
            else maxRooms = Math.max(maxRooms, ++rooms);
        }
        return maxRooms;
    }
}

