import "sort"

func minMeetingRooms(intervals [][]int) int {
    // Events as {time, kind}: at equal times, ends (0) free rooms first,
    // then zero-length meetings (1) use a room for an instant, then starts (2)
    events := [][2]int{}
    for _, iv := range intervals {
        if iv[0] == iv[1] {
            events = append(events, [2]int{iv[0], 1})
        } else {
            events = append(events, [2]int{iv[0], 2}, [2]int{iv[1], 0})
        }
    }
    sort.Slice(events, func(a, b int) bool {
        if events[a][0] != events[b][0] {
            return events[a][0] < events[b][0]
        }
        return events[a][1] < events[b][1]
    })
    rooms, maxRooms := 0, 0
    for _, ev := range events {
        switch ev[1] {
        case 0:
            rooms--
        case 1:
            maxRooms = max(maxRooms, rooms+1)
        default:
            rooms++
            maxRooms = max(maxRooms, rooms)
        }
    }
    return maxRooms
}
